import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-credentials.json"), "utf8"),
);
const models = emitModels(contract.models, "credentialStatusSchema");
let go =
  '// Code generated by scripts/generate-workforce-credentials.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
let ts =
  '// Generated by scripts/generate-workforce-credentials.mjs.\nimport { z } from "zod";\n\n';
ts += `export const CREDENTIAL_STATUSES=${JSON.stringify(contract.statuses)} as const;\nexport const credentialStatusSchema=z.enum(${JSON.stringify(Object.keys(contract.statuses))});\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/credential_types.go",
  go + models.go,
  "packages/api/src/credential-contract.ts",
  ts + models.ts,
  "credentials",
);
